"""1492 (#11 power_upgrade_variants): Record-MissionCoverage-v1488.ps1 with -TakedownKind possess. On the lab level the
human possession worked once (1461a) and failed whenever the guard had been moved by the lab placement (1473a, 1481a,
1490a: the guard was still at a placed spot, and 3 m behind it is outside the wall). On Edge of the World the square
overseer walks his own route and is taken reliably (1448, 1489a). 'possess' grants Possession and possession_parasite
(possess humans) natively (lab-only grants), stands Corvo -Behind the overseer like a takedown, aims the power 1.3 s and
releases at him, walks the possessed overseer forward 1.5 s, and leaves with a power tap 4.5 s later. The case passes on
the native possession (power_possession_cast_out and the overseer's possession_exit scene in the scene watch) with the
overseer alive in both worlds. Generated by make_mission_coverage_v1492.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-MissionCoverage-v1488.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
rep("[ValidateSet('choke','lethal')][string]$TakedownKind='choke'", "[ValidateSet('choke','lethal','possess')][string]$TakedownKind='choke'")
first = s.index('\n') + 1
s = s[:first] + "# 1492 (#11): -TakedownKind possess - Possession of a human (possession_parasite) on a mission NPC. Generated by make_mission_coverage_v1492.py.\n" + s[first:]
rep("    if($case-eq'takedown'){\n     C $source 'coop_player_health_hold on';",
    "    if($case-eq'takedown'){\n"
    "     if($TakedownKind-eq'possess'){foreach($u in 'models/powers/possession/possession.inventoryitem','components/characters/player/base/attributes/possession_parasite.inventoryitem'){C $source \"coop_grant_named $u\";Start-Sleep -Milliseconds 900};$row.grant=try{(S $source '.observer-camera.json').itemGrant.named}catch{$null}}\n"
    "     C $source 'coop_player_health_hold on';")
rep("$inputArgs=if($TakedownKind-eq'choke'){@('-Button','RightShoulder','-DurationMs','6500')}else{@('-RightTrigger','255','-DurationMs','200')}",
    "$inputArgs=if($TakedownKind-eq'choke'){@('-Button','RightShoulder','-DurationMs','6500')}elseif($TakedownKind-eq'possess'){@('-LeftTrigger','255','-DurationMs','1300')}else{@('-RightTrigger','255','-DurationMs','200')}")
rep("      if(!$acted-and$t-ge700){",
    "      if($TakedownKind-eq'possess'-and$acted-and!$row.possWalk-and$t-ge$row.actedAt+2500){$row.possWalk=$t;$null=Start-Process (Get-Process -Id $PID).Path -ArgumentList @('-NoProfile','-File',\"$lab/Send-D2Input.ps1\",'-Role',$source,'-LeftY','32767','-DurationMs','1500') -WindowStyle Hidden -PassThru}\n"
    "      if($TakedownKind-eq'possess'-and$acted-and!$row.possExit-and$t-ge$row.actedAt+7000){$row.possExit=$t;$null=Start-Process (Get-Process -Id $PID).Path -ArgumentList @('-NoProfile','-File',\"$lab/Send-D2Input.ps1\",'-Role',$source,'-LeftTrigger','255','-DurationMs','300') -WindowStyle Hidden -PassThru}\n"
    "      if(!$acted-and$t-ge700){")
rep("     $expected=if($HitAt){'alive'}elseif($TakedownKind-eq'choke'){'unconscious'}else{'dead'}",
    "     if($TakedownKind-eq'possess'){$mid=@(Get-Content \"$out/$key-midnight.ndjson\" -ErrorAction SilentlyContinue)\n"
    "      $row.possessScenes=@($mid|Select-String -Pattern 'possession_[a-z_]+' -AllMatches|ForEach-Object {$_.Matches.Value}|Sort-Object -Unique)\n"
    "      $row.checks.Add(\"Possession scenes $(@($row.possessScenes)-join ', '); outcome host $($row.outcome.host), client $($row.outcome.client)\")\n"
    "      if($row.possessScenes-notcontains'possession_cast_out'){throw 'No native possession (no power_possession_cast_out)'};if(!@($row.possessScenes|Where-Object {$_-like'possession_exit*'}).Count){throw 'No possession exit on the target'}\n"
    "      if($row.outcome.host-ne'alive'-or$row.outcome.client-ne'alive'){throw 'The possessed target did not end alive in both worlds'}}else{\n"
    "     $expected=if($HitAt){'alive'}elseif($TakedownKind-eq'choke'){'unconscious'}else{'dead'}")
rep("     $row.checks.Add(\"Native $TakedownKind of $($tg[0].definition): source states $($row.sourceStates-join ','); $expected in both worlds\")}",
    "     $row.checks.Add(\"Native $TakedownKind of $($tg[0].definition): source states $($row.sourceStates-join ','); $expected in both worlds\")}}")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-MissionCoverage-v1492.ps1').write_bytes(out.encode('utf-8'))
print('ok')
